Seeing it directly
Numbers aside, the clearest evidence is just looking at the images. Below, each row is one starting image; each column is the reconstruction after forward-backward diffusion at an increasing reversal timestep. At small \(t\) the reconstruction is nearly pixel-identical to the original. At larger \(t\), fine texture is the first thing to change, followed eventually by pose, composition, and — at the largest \(t\) we tested — occasionally the object itself.

library(jpeg)
library(grid)

manifest &lt;- read_csv("data/image_grid_manifest.csv", show_col_types = FALSE)
t_values &lt;- sort(unique(manifest$step_reverse[manifest$step_reverse &gt; 0]))
image_ids &lt;- unique(manifest$image_id)

grid.newpage()
n_rows &lt;- length(image_ids)
n_cols &lt;- length(t_values) + 1
pushViewport(viewport(layout = grid.layout(
  n_rows + 1, n_cols,
  heights = unit(c(1.5, rep(5, n_rows)), c("lines", rep("null", n_rows)))
)))

draw_label &lt;- function(label, col) {
  pushViewport(viewport(layout.pos.row = 1, layout.pos.col = col))
  grid.text(label, gp = gpar(fontsize = 9))
  popViewport()
}

draw_cell &lt;- function(path, row, col) {
  img &lt;- readJPEG(path)
  pushViewport(viewport(layout.pos.row = row + 1, layout.pos.col = col))
  grid.raster(img)
  popViewport()
}

draw_label("original", 1)
for (c in seq_along(t_values)) draw_label(paste0("t=", t_values[c]), c + 1)

for (r in seq_along(image_ids)) {
  row_data &lt;- manifest |&gt; filter(image_id == image_ids[r])
  start_path &lt;- row_data$path[row_data$step_reverse == 0]
  draw_cell(start_path, r, 1)
  for (c in seq_along(t_values)) {
    t_path &lt;- row_data$path[row_data$step_reverse == t_values[c]]
    if (length(t_path) == 1) {
      draw_cell(t_path, r, c + 1)
    }
  }
}







Figure 4: Original (leftmost column) vs. forward-backward reconstructions at increasing t.

The first six hours
Press play, or jump to an event. Playback speeds up automatically through the long, quiet stretches and slows down for the burns. There are four panels. The ground track follows Apollo 11 over the rotating Earth. The inertial view looks down on the orbit from above its plane, in a frame that does not rotate, which is where the orbital mechanics is easiest to see. The 3D view is a computer-generated model of the Saturn V, built to scale and flown along the reconstructed trajectory, with staging, tower jettison and the transposition and docking. The last panel scrolls the crew’s and Mission Control’s words with the clock. Turn the sound on and choose Real time to hear NASA’s recordings wherever they exist for that moment; the launch film plays in the same panel around liftoff.

data = FileAttachment("data/part1.json").json()
track = data.track
times = track.map(d =&gt; d[0])
events = data.events
T_MIN = -60
T_MAX = 6 * 3600












































phases = [
  [-60, "On the pad"],
  [0.63, "First stage (S-IC)"],
  [162.3, "Second stage (S-II)"],
  [549.0, "Third stage (S-IVB), first burn"],
  [709.33, "Earth parking orbit"],
  [9856.2, "Translunar injection burn"],
  [10203.03, "Coasting away from Earth"],
  [11723.0, "Transposition and docking"],
  [12243.7, "Translunar coast, docked"]
]
jumps = [
  ["Liftoff", 0], ["Max Q", 83], ["Staging", 162.3], ["Orbit", 709.33],
  ["TLI burn", 9850], ["TLI", 10213.03], ["Docking", 12243.7]
]
















viewof T = {
  const warp = t =&gt; t &lt; 0 ? 4 : t &lt; 715 ? 8 : t &lt; 9800 ? 240 : t &lt; 10220 ? 12 : t &lt; 12300 ? 90 : 300;
  const range = htl.html`&lt;input type="range" min=${T_MIN} max=${T_MAX} step="0.5" value="-20"&gt;`;
  const play = htl.html`&lt;button type="button" class="primary"&gt;▶ Play&lt;/button&gt;`;
  const speed = htl.html`&lt;select class="a11-chip"&gt;
      &lt;option value="rt"&gt;Real time&lt;/option&gt;&lt;option value="0.5"&gt;½×&lt;/option&gt;&lt;option value="1" selected&gt;1×&lt;/option&gt;&lt;option value="3"&gt;3×&lt;/option&gt;&lt;/select&gt;`;
  const chips = htl.html`&lt;div class="a11-chips"&gt;${jumps.map(([label, t]) =&gt;
      htl.html`&lt;button type="button" class="a11-chip" data-t=${t}&gt;${label}&lt;/button&gt;`)}&lt;/div&gt;`;
  const root = htl.html`&lt;div&gt;&lt;div class="a11-player"&gt;${play}${range}${speed}&lt;/div&gt;${chips}&lt;/div&gt;`;
  let running = false, last = null, raf = null;
  const set = v =&gt; {
    root.value = Math.max(T_MIN, Math.min(T_MAX, v));
    range.value = root.value;
    root.dispatchEvent(new Event("input", {bubbles: true}));
  };
  const tick = now =&gt; {
    if (!running) return;
    if (last != null) {
      const dt = Math.min(0.1, (now - last) / 1000);
      root.rate = speed.value === "rt" ? 1 : warp(root.value) * (+speed.value);
      set(root.value + dt * root.rate);
      if (root.value &gt;= T_MAX) toggle(false);
    }
    last = now;
    raf = requestAnimationFrame(tick);
  };
  const toggle = on =&gt; {
    running = on; last = null; root.rate = 0; root.running = on;
    play.textContent = on ? "❚❚ Pause" : "▶ Play";
    if (on) { if (root.value &gt;= T_MAX) set(T_MIN); raf = requestAnimationFrame(tick); }
    else cancelAnimationFrame(raf);
  };
  play.onclick = () =&gt; toggle(!running);
  range.oninput = e =&gt; { e.stopPropagation(); set(+range.value); };
  chips.onclick = e =&gt; { const b = e.target.closest("button"); if (b) set(+b.dataset.t); };
  root.value = -20;
  root.rate = 0;
  root.running = false;
  root.setT = set;
  root.setSpeed = v =&gt; { speed.value = v; };
  root.play = () =&gt; { if (!running) toggle(true); };
  invalidation.then(() =&gt; cancelAnimationFrame(raf));
  return root;
}







state = {
  let i = Math.max(0, Math.min(track.length - 2, d3.bisectRight(times, T) - 1));
  const a = track[i], b = track[i + 1];
  const f = Math.max(0, Math.min(1, (T - a[0]) / (b[0] - a[0])));
  const s = {};
  data.meta.columns.forEach((c, j) =&gt; {
    if (c === "src") return;
    let va = a[j], vb = b[j];
    if (c === "lon" && Math.abs(vb - va) &gt; 180) vb += vb &lt; va ? 360 : -360;
    s[c] = va + f * (vb - va);
  });
  if (s.lon &gt; 180) s.lon -= 360;
  if (s.lon &lt; -180) s.lon += 360;
  s.get = T;
  s.src = (f &lt; 0.02) ? a[13] : (f &gt; 0.98 ? b[13] : Math.max(a[13], b[13]) === 0 ? 1 : Math.max(a[13], b[13]));
  s.phase = phases.filter(p =&gt; p[0] &lt;= T).at(-1)[1];
  s.i = i;
  return s;
}







fmtGET = t =&gt; {
  const sign = t &lt; 0 ? "T−" : "";
  t = Math.abs(t);
  const h = Math.floor(t / 3600), m = Math.floor(t % 3600 / 60), s = t % 60;
  return `${sign}${String(h).padStart(3, "0")}:${String(m).padStart(2, "0")}:${s.toFixed(1).padStart(4, "0")}`;
}
fmt = (x, d = 1) =&gt; x.toLocaleString("en-GB", {minimumFractionDigits: d, maximumFractionDigits: d})
















hud = {
  const s = state, src = srcInfo[s.src];
  const FT = 3.28084;
