plane = {
  // Basis in the plane of the translunar orbit: e1 towards the TLI position, e2 along-track.
  const tli = track.find(d =&gt; Math.abs(d[0] - 10213.03) &lt; 1e-6);
  const r = [tli[1], tli[2], tli[3]];
  const k = track.find(d =&gt; d[0] &gt; 10300);
  const r2 = [k[1], k[2], k[3]];
  const cross = (a, b) =&gt; [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
  const norm = a =&gt; { const n = Math.hypot(...a); return a.map(x =&gt; x / n); };
  const hN = norm(cross(r, r2)), e1 = norm(r), e2 = cross(hN, e1);
  return {e1, e2, hN, proj: p =&gt; [p[0]*e1[0]+p[1]*e1[1]+p[2]*e1[2], p[0]*e2[0]+p[1]*e2[1]+p[2]*e2[2]]};
}
