drawInertial = (state, T) =&gt; {
  const w = panelW, h = w;
  const span = zoomMode === "Near Earth" ? 11000 : zoomMode === "Earth–Moon" ? 430000
             : Math.max(9500, Math.min(430000, 1.35 * state.r_km));
  const sc = (Math.min(w, h) / 2 - 8) / span;
  const X = q =&gt; w / 2 + q[0] * sc, Y = q =&gt; h / 2 - q[1] * sc;
  const pts = track.map(d =&gt; plane.proj([d[1], d[2], d[3]]));
  const line = arr =&gt; arr.map((q, i) =&gt; `${i ? "L" : "M"}${X(q).toFixed(1)},${Y(q).toFixed(1)}`).join("");
  const past = pts.slice(0, state.i + 1).concat([plane.proj([state.x, state.y, state.z])]);
  const futurePts = pts.slice(state.i + 1);
  const longPts = data.long_track.map(d =&gt; plane.proj([d[1], d[2], d[3]]));
  const moonPts = data.moon.map(d =&gt; plane.proj([d[1], d[2], d[3]]));
  const mi = Math.max(0, d3.bisectRight(data.moon.map(d =&gt; d[0]), T) - 1);
  const m0 = data.moon[mi], m1 = data.moon[Math.min(mi + 1, data.moon.length - 1)];
  const f = m1[0] &gt; m0[0] ? (T - m0[0]) / (m1[0] - m0[0]) : 0;
  const mNow = plane.proj([0, 1, 2].map(j =&gt; m0[j + 1] + f * (m1[j + 1] - m0[j + 1])));
  const sNow = plane.proj([state.x, state.y, state.z]);
  const tArr = data.checks.find(c =&gt; c[0].startsWith("Arrival at the Moon, GET"))[2] * 3600;
  const ai = Math.max(0, d3.bisectRight(data.moon.map(d =&gt; d[0]), tArr) - 1);
  const a0 = data.moon[ai], a1 = data.moon[ai + 1], fa = (tArr - a0[0]) / (a1[0] - a0[0]);
  const mArr = plane.proj([0, 1, 2].map(j =&gt; a0[j + 1] + fa * (a1[j + 1] - a0[j + 1])));
  const earthR = 6378 * sc, moonR = Math.max(3, 1737 * sc);
  const tick = span &gt; 50000 ? 100000 : span &gt; 15000 ? 10000 : 2000;
  const rings = d3.range(tick, span * 1.5, tick).slice(0, 6);
  return htl.html`&lt;div class="a11-panel"&gt;&lt;h4&gt;Inertial view, looking down on the orbit plane&lt;/h4&gt;
