      ${rings.map(rr =&gt; htl.svg`&lt;circle cx=${w/2} cy=${h/2} r=${rr * sc} fill="none" stroke="#ffffff12"/&gt;`)}
      ${htl.svg`&lt;text x="8" y=${h - 8} fill="#ffffff70" font-size="11"&gt;rings every ${fmt(tick, 0)} km&lt;/text&gt;`}
      ${span &gt; 60000 ? htl.svg`&lt;path d="${line(moonPts)}" fill="none" stroke="#ffffff22" stroke-dasharray="2 4"/&gt;` : ""}
      ${span &gt; 60000 ? htl.svg`&lt;path d="${line(longPts)}" fill="none" stroke="#e9c46a55" stroke-dasharray="5 4"/&gt;` : ""}
      &lt;circle cx=${w/2} cy=${h/2} r=${Math.max(2, earthR)} fill="#1d4e89" stroke="#6fa8dc" stroke-width="0.8"/&gt;
      &lt;path d="${line(futurePts)}" fill="none" stroke="#ffffff35" stroke-dasharray="3 3"/&gt;
      &lt;path d="${line(past)}" fill="none" stroke="#f4a261" stroke-width="1.8"/&gt;
      ${span &gt; 60000 ? htl.svg`&lt;circle cx=${X(mArr)} cy=${Y(mArr)} r=${moonR + 3} fill="none" stroke="#bbb" stroke-dasharray="2 2"/&gt;
        &lt;text x=${X(mArr) + moonR + 6} y=${Y(mArr) + 14} fill="#999" font-size="10"&gt;Moon at arrival, ~75 h&lt;/text&gt;` : ""}
      &lt;circle cx=${X(mNow)} cy=${Y(mNow)} r=${moonR} fill="#bbb"/&gt;
      ${htl.svg`&lt;text x=${X(mNow) + moonR + 4} y=${Y(mNow) + 4} fill="#ccc" font-size="11"&gt;Moon&lt;/text&gt;`}
      &lt;circle cx=${X(sNow)} cy=${Y(sNow)} r="4.5" fill="#e76f51" stroke="#fff" stroke-width="1.2"/&gt;
    &lt;/svg&gt;
    &lt;div class="a11-legend" style="margin:.4rem .25rem 0"&gt;
      &lt;span style="--c:#f4a261"&gt;Flown so far&lt;/span&gt;&lt;span style="--c:#9aa3ad"&gt;Still to come&lt;/span&gt;
