viewof T = {
  const warp = t =&gt; {
    if (Math.abs(t - burnsAt.ev) &lt; 90 || Math.abs(t - burnsAt.mcc) &lt; 120) return 4;
    if (t &gt; burnsAt.l1 - 300 && t &lt; burnsAt.l1c + 120) return 15;
    if (t &gt; burnsAt.l2 - 120 && t &lt; burnsAt.l2c + 120) return 4;
    if (t &gt; 272483 - 900 && t &lt; 274529 + 600) return 60;
    if (t &gt; burnsAt.l1c) return 150;
    if (t &gt; 255000) return 400;
    return 1500;
  };
  const range = htl.html`&lt;input type="range" min=${T_MIN} max=${T_MAX} step="1" value=${burnsAt.ev - 60}&gt;`;
  const play = htl.html`&lt;button type="button" class="primary"&gt;▶ Play&lt;/button&gt;`;
  const speed = htl.html`&lt;select class="a11-chip"&gt;
      &lt;option value="rt"&gt;Real time&lt;/option&gt;&lt;option value="0.5"&gt;½×&lt;/option&gt;&lt;option value="1" selected&gt;1×&lt;/option&gt;&lt;option value="3"&gt;3×&lt;/option&gt;&lt;option value="10"&gt;10×&lt;/option&gt;&lt;/select&gt;`;
  const chips = htl.html`&lt;div class="a11-chips"&gt;${jumps.map(([label, t]) =&gt;
      htl.html`&lt;button type="button" class="a11-chip" data-t=${t}&gt;${label}&lt;/button&gt;`)}&lt;/div&gt;`;
  const root = htl.html`&lt;div&gt;&lt;div class="a11-player"&gt;${play}${range}${speed}&lt;/div&gt;${chips}&lt;/div&gt;`;
  let running = false, last = null, raf = null;
  const set = v =&gt; {
    root.value = Math.max(T_MIN, Math.min(T_MAX, v));
    range.value = root.value;
    root.dispatchEvent(new Event("input", {bubbles: true}));
  };
  const tick = now =&gt; {
    if (!running) return;
    if (last != null) {
      const dt = Math.min(0.1, (now - last) / 1000);
      root.rate = speed.value === "rt" ? 1 : warp(root.value) * (+speed.value);
      set(root.value + dt * root.rate);
      if (root.value &gt;= T_MAX) toggle(false);
    }
    last = now;
    raf = requestAnimationFrame(tick);
  };
  const toggle = on =&gt; {
    running = on; last = null; root.rate = 0; root.running = on;
    play.textContent = on ? "❚❚ Pause" : "▶ Play";
    if (on) { if (root.value &gt;= T_MAX) set(T_MIN); raf = requestAnimationFrame(tick); }
    else cancelAnimationFrame(raf);
  };
  play.onclick = () =&gt; toggle(!running);
  range.oninput = e =&gt; { e.stopPropagation(); set(+range.value); };
  chips.onclick = e =&gt; { const b = e.target.closest("button"); if (b) set(+b.dataset.t); };
  root.value = burnsAt.ev - 60;
  root.rate = 0;
  root.running = false;
  root.setT = set;
  root.setSpeed = v =&gt; { speed.value = v; };
  invalidation.then(() =&gt; cancelAnimationFrame(raf));
  return root;
}







tabAt = (rows, t, n = 3) =&gt; {
  const ts = rows._t ?? (rows._t = rows.map(d =&gt; d[0]));
  const i = Math.max(0, Math.min(rows.length - 2, d3.bisectRight(ts, t) - 1));
  const a = rows[i], b = rows[i + 1], f = (t - a[0]) / (b[0] - a[0]);
  return d3.range(1, n + 1).map(j =&gt; a[j] + f * (b[j] - a[j]));
}
vec = ({
  sub: (a, b) =&gt; a.map((x, i) =&gt; x - b[i]),
  dot: (a, b) =&gt; a[0] * b[0] + a[1] * b[1] + a[2] * b[2],
  cross: (a, b) =&gt; [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]],
  norm: a =&gt; Math.hypot(a[0], a[1], a[2]),
  unit: a =&gt; { const n = Math.hypot(a[0], a[1], a[2]); return a.map(x =&gt; x / n); },
  scale: (a, k) =&gt; a.map(x =&gt; x * k)
})
rowAt = t =&gt; {
  const i = Math.max(0, Math.min(track.length - 2, d3.bisectRight(times, t) - 1));
  const a = track[i], b = track[i + 1], f = Math.max(0, Math.min(1, (t - a[0]) / (b[0] - a[0])));
  const r = a.map((x, j) =&gt; x + f * (b[j] - x));
  if (Math.abs(b[12] - a[12]) &gt; 180) {           // selenographic longitude wraps
    const lb = b[12] + (b[12] &lt; a[12] ? 360 : -360);
    r[12] = a[12] + f * (lb - a[12]);
    if (r[12] &gt; 180) r[12] -= 360; if (r[12] &lt; -180) r[12] += 360;
  }
  r.i = i; r.src = f &lt; 0.02 ? a[13] : f &gt; 0.98 ? b[13] : Math.max(a[13], b[13]) || 1;
  return r;
}
// Earth visible from the spacecraft? Signed clearance (km) of the line to Earth's centre past the lunar limb.
earthClear = r =&gt; {
  const s = [r[1], r[2], r[3]], w = [-r[4], -r[5], -r[6]];
  const u = vec.unit(vec.scale(s, -1)), along = vec.dot(w, u);
  if (along &lt; 0) return 1e4;
  return vec.norm(vec.sub(w, vec.scale(u, along))) - RM;
}
losTimes = {
  const out = [];
  let prev = null;
  for (const d of track) {
    if (d[0] &lt; 270000) continue;
    const c = earthClear(d);
    if (prev && (prev[1] &gt; 0) !== (c &gt; 0)) {
      const tc = prev[0] + (d[0] - prev[0]) * prev[1] / (prev[1] - c);
      out.push([tc, prev[1] &gt; 0 ? "LOS" : "AOS"]);
    }
    prev = [d[0], c];
  }
  return out;
}





































state = {
  const r = rowAt(T), s = {};
  data.meta.columns.forEach((c, j) =&gt; { s[c] = r[j]; });
  s.get = T; s.i = r.i; s.src = r.src;
  s.rE = Math.hypot(r[1], r[2], r[3]);
  s.rM = Math.hypot(r[4], r[5], r[6]);
  s.clear = earthClear(r);
  s.phase = phases.filter(p =&gt; p[0] &lt;= T).at(-1)[1];
  // Moon-relative osculating orbit from a centred difference.
  const a = rowAt(T - 5), b = rowAt(T + 5);
  const rv = [r[4], r[5], r[6]], vv = [0, 1, 2].map(j =&gt; (b[4 + j] - a[4 + j]) / 10);
  const mu = 4902.80, rn = vec.norm(rv), vn = vec.norm(vv);
  const sma = 1 / (2 / rn - vn * vn / mu), h = vec.cross(rv, vv);
  const ev = vec.sub(vec.scale(vec.cross(vv, h), 1 / mu), vec.scale(rv, 1 / rn)), e = vec.norm(ev);
  s.orb = {apo: sma &gt; 0 ? sma * (1 + e) - RM : Infinity, peri: sma * (1 - e) - RM, e, period: sma &gt; 0 ? 2 * Math.PI * Math.sqrt(sma ** 3 / mu) : NaN};
  s.rev = T &lt; burnsAt.l1 ? 0 : 1 + losTimes.filter(([t, k]) =&gt; k === "LOS" && t &gt; burnsAt.l1c && t &lt;= T).length;
  return s;
}







