// Frames for the Earth–Moon panel.
frames = {
  const moonAt = t =&gt; tabAt(data.moon, t);
  const moonVel = t =&gt; vec.scale(vec.sub(moonAt(t + 300), moonAt(t - 300)), 1 / 600);
  // Rotating frame: x towards the Moon, z along the Moon's orbital angular momentum.
  const rot = (p, t) =&gt; {
    const m = moonAt(t), ex = vec.unit(m), ez = vec.unit(vec.cross(m, moonVel(t))), ey = vec.cross(ez, ex);
    return [vec.dot(p, ex), vec.dot(p, ey)];
  };
  // Inertial frame: the Moon's orbit plane at LOI, x towards the Moon at LOI.
  const tL = burnsAt.l1, m0 = moonAt(tL), ix = vec.unit(m0), iz = vec.unit(vec.cross(m0, moonVel(tL))), iy = vec.cross(iz, ix);
  const ine = p =&gt; [vec.dot(p, ix), vec.dot(p, iy)];
  // Moon-centred frame: the plane of the final lunar orbit, x towards Earth at LOI-1.
  const r2 = track.find(d =&gt; d[0] &gt; burnsAt.l2c + 600), r3 = track.find(d =&gt; d[0] &gt; burnsAt.l2c + 1200);
  const hz = vec.unit(vec.cross([r2[4], r2[5], r2[6]], [r3[4] - r2[4], r3[5] - r2[5], r3[6] - r2[6]]));
  const e0 = vec.scale(m0, -1);
  const lx = vec.unit(vec.sub(e0, vec.scale(hz, vec.dot(e0, hz)))), ly = vec.cross(hz, lx);
  const loc = p =&gt; [vec.dot(p, lx), vec.dot(p, ly)];
  const sample = (rows, dt) =&gt; rows.filter((d, i) =&gt; i === 0 || i === rows.length - 1 || Math.floor(d[0] / dt) !== Math.floor(rows[i - 1][0] / dt));
  const coarse = sample(track, 900);
  const F = {
    moonAt, rot, ine, loc,
    trackRot: coarse.map(d =&gt; [d[0], ...rot([d[1], d[2], d[3]], d[0])]),
    trackIne: coarse.map(d =&gt; [d[0], ...ine([d[1], d[2], d[3]])]),
    trackLoc: track.filter(d =&gt; Math.hypot(d[4], d[5], d[6]) &lt; 90000).map(d =&gt; [d[0], ...loc([d[4], d[5], d[6]])]),
    noMccRot: data.free_return.no_mcc.map(d =&gt; rot([d[1], d[2], d[3]], d[0])),
    noLoiRot: data.free_return.no_loi.map(d =&gt; rot([d[1], d[2], d[3]], d[0])),
    noMccIne: data.free_return.no_mcc.map(d =&gt; ine([d[1], d[2], d[3]])),
    noLoiIne: data.free_return.no_loi.map(d =&gt; ine([d[1], d[2], d[3]])),
    moonIne: data.moon.map(d =&gt; ine([d[1], d[2], d[3]]))
  };
  const ext = (...sets) =&gt; {
    const all = sets.flat();
    const xs = d3.extent(all, q =&gt; q[0]), ys = d3.extent(all, q =&gt; q[1]);
    const px = 0.04 * (xs[1] - xs[0]), py = 0.04 * (ys[1] - ys[0]);
    return [xs[0] - px, xs[1] + px, ys[0] - py, ys[1] + py];
  };
  const pts = a =&gt; a.map(d =&gt; [d[1], d[2]]);
  return Object.assign(F, {
    extRot: ext(pts(F.trackRot), F.noMccRot, F.noLoiRot, [[0, 0]]),
    extIne: ext(pts(F.trackIne), F.noMccIne, F.noLoiIne, F.moonIne.filter((q, i) =&gt; data.moon[i][0] &lt;= T_MAX), [[0, 0]])
  });
}







