dsky = {
  const el = htl.html`&lt;div class="a11-dsky"&gt;
    &lt;div class="lights"&gt;&lt;span data-l="comp"&gt;COMP ACTY&lt;/span&gt;&lt;span data-l="prog"&gt;PROG&lt;/span&gt;&lt;span data-l="alt"&gt;ALT&lt;/span&gt;&lt;span data-l="vel"&gt;VEL&lt;/span&gt;&lt;/div&gt;
    &lt;div class="row"&gt;&lt;div&gt;&lt;div class="lab"&gt;PROG&lt;/div&gt;&lt;div class="dig" data-d="prog"&gt;00&lt;/div&gt;&lt;/div&gt;
      &lt;div&gt;&lt;div class="lab"&gt;VERB&lt;/div&gt;&lt;div class="dig" data-d="verb"&gt;06&lt;/div&gt;&lt;/div&gt;&lt;div&gt;&lt;div class="lab"&gt;NOUN&lt;/div&gt;&lt;div class="dig" data-d="noun"&gt;00&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;
    &lt;div class="reg" data-d="r1"&gt;+00000&lt;/div&gt;&lt;div class="reg" data-d="r2"&gt;+00000&lt;/div&gt;&lt;div class="reg" data-d="r3"&gt;+00000&lt;/div&gt;
    &lt;div class="cap"&gt;&lt;/div&gt;&lt;/div&gt;`;
  const q = s =&gt; el.querySelector(s);
  const reg = v =&gt; (v &lt; 0 ? "−" : "+") + String(Math.min(99999, Math.round(Math.abs(v)))).padStart(5, "0");
  const lpdAt = t =&gt; {
    // Look angle to the guidance aim point, below the LM's body plane, from the reconstruction.
    const r = tabAt(track, t, 3), u = tabAt(data.thrust, t, 3);
    const o = tabAt(data.moon_orient, t, 9);
    const lat = M.aim_point[0] * Math.PI / 180, lon = M.aim_point[1] * Math.PI / 180, R = M.r_site;
    const b = [Math.cos(lat) * Math.cos(lon), Math.cos(lat) * Math.sin(lon), Math.sin(lat)].map(x =&gt; x * R);
    const a = [o[0] * b[0] + o[1] * b[1] + o[2] * b[2], o[3] * b[0] + o[4] * b[1] + o[5] * b[2], o[6] * b[0] + o[7] * b[1] + o[8] * b[2]];
    const l = [a[0] - r[0], a[1] - r[1], a[2] - r[2]], n = Math.hypot(...l), un = Math.hypot(...u);
    return Math.asin(-(l[0] * u[0] + l[1] * u[1] + l[2] * u[2]) / n / un) * 180 / Math.PI;
  };
  function update(s, t) {
    const alarm = data.alarms.find(([ta]) =&gt; t &gt;= ta && t &lt; ta + 10);
    let prog = "00", noun = "00", r1 = 0, r2 = 0, r3 = 0, verb = "06", cap = "";
    if (t &gt;= M.pdi - 480 && t &lt; M.p64) { prog = "63"; noun = "63"; r1 = Math.hypot(s.hvel_fps, s.hdot_fps); r2 = s.hdot_fps * 10; r3 = s.alt_ft; cap = "V06 N63: speed, altitude rate (0.1 ft/s), altitude"; }
    else if (t &gt;= M.p64 && t &lt; M.p66) { prog = "64"; noun = "64"; const tt = Math.max(0, Math.round((M.p66 - t))); r1 = Math.min(99, tt) * 1000 + Math.max(0, Math.round(lpdAt(t))); r2 = s.hdot_fps * 10; r3 = s.alt_ft; cap = "V06 N64: time left for redesignation and LPD angle, altitude rate, altitude"; }
    else if (t &gt;= M.p66 && t &lt; M.engine_stop + 2) { prog = "66"; noun = "60"; r1 = s.hvel_fps * 10; r2 = s.hdot_fps * 10; r3 = s.alt_ft; cap = "V06 N60: forward velocity, altitude rate (0.1 ft/s), altitude"; }
    else if (t &gt;= M.engine_stop + 2) { prog = "68"; noun = "43"; r1 = M.landing_site[0] * 100; r2 = M.landing_site[1] * 100; r3 = 0; cap = "V06 N43: latitude, longitude (0.01°), altitude"; }
    else { cap = "Before the descent the displays changed with each checklist step; not reconstructed."; }
    if (alarm) { verb = "05"; noun = "09"; r1 = +alarm[1]; r2 = 0; r3 = 0; cap = `Program alarm ${alarm[1]}: the computer was short of time and restarted its jobs, keeping the guidance running.`; }
    q('[data-d="prog"]').textContent = prog; q('[data-d="verb"]').textContent = verb; q('[data-d="noun"]').textContent = noun;
    q('[data-d="r1"]').textContent = alarm ? "+0" + alarm[1] : reg(r1);
    q('[data-d="r2"]').textContent = reg(r2); q('[data-d="r3"]').textContent = reg(r3);
    q('[data-l="prog"]').classList.toggle("on", !!alarm);
    q('[data-l="comp"]').classList.toggle("on", t &gt; M.pdi - 480 && t &lt; M.engine_stop && (Math.floor(t * 3) % 4 === 0 || !!alarm));
    q('[data-l="alt"]').classList.toggle("on", t &gt; M.pdi && t &lt; 369482);
    q('[data-l="vel"]').classList.toggle("on", t &gt; M.pdi && t &lt; 369482);
    q(".cap").textContent = cap;
  }
  return {el, update};
}







