viewof T = {
  const warp = t =&gt; {
    if (t &gt;= M.liftoff - 10 && t &lt;= M.insertion + 20) return 3;
    if (t &gt;= M.ei - 60 && t &lt;= M.splash + 60) return 4;
    if (t &gt;= M.braking && t &lt;= M.dock_contact + 300) return 20;
    if ([M.csi, M.cdh, M.tpi, M.tei, M.final_sep].some(([a, b]) =&gt; t &gt; a - 20 && t &lt; b + 20)) return 10;
    if (Math.abs(t - M.mcc5) &lt; 30 || Math.abs(t - M.cm_sm_sep) &lt; 60 || Math.abs(t - M.jettison) &lt; 40) return 10;
    if (t &gt; M.tei[1] + 3 * 3600 && t &lt; M.ei - 1800) return 6000;
    if (t &gt; M.dock_contact && t &lt; M.tei[0]) return 600;
    if (t &gt; M.tei[1] && t &lt; M.ei) return 1200;
    return 240;
  };
  const range = htl.html`&lt;input type="range" min=${T_MIN} max=${T_MAX} step="0.5" value=${M.liftoff - 20}&gt;`;
  const play = htl.html`&lt;button type="button" class="primary"&gt;▶ Play&lt;/button&gt;`;
  const speed = htl.html`&lt;select class="a11-chip"&gt;
      &lt;option value="rt"&gt;Real time&lt;/option&gt;&lt;option value="0.5"&gt;½×&lt;/option&gt;&lt;option value="1" selected&gt;1×&lt;/option&gt;&lt;option value="3"&gt;3×&lt;/option&gt;&lt;option value="10"&gt;10×&lt;/option&gt;&lt;/select&gt;`;
  const chips = htl.html`&lt;div class="a11-chips"&gt;${jumps.map(([label, t]) =&gt;
      htl.html`&lt;button type="button" class="a11-chip" data-t=${t}&gt;${label}&lt;/button&gt;`)}&lt;/div&gt;`;
  const root = htl.html`&lt;div&gt;&lt;div class="a11-player"&gt;${play}${range}${speed}&lt;/div&gt;${chips}&lt;/div&gt;`;
  let running = false, last = null, raf = null;
  const set = v =&gt; {
    root.value = Math.max(T_MIN, Math.min(T_MAX, v));
    range.value = root.value;
    root.dispatchEvent(new Event("input", {bubbles: true}));
  };
  const tick = now =&gt; {
    if (!running) return;
    if (last != null) {
      const dt = Math.min(0.1, (now - last) / 1000);
      root.rate = speed.value === "rt" ? 1 : warp(root.value) * (+speed.value);
      set(root.value + dt * root.rate);
      if (root.value &gt;= T_MAX) toggle(false);
    }
    last = now;
    raf = requestAnimationFrame(tick);
  };
  const toggle = on =&gt; {
    running = on; last = null; root.rate = 0; root.running = on;
    play.textContent = on ? "❚❚ Pause" : "▶ Play";
    if (on) { if (root.value &gt;= T_MAX) set(T_MIN); raf = requestAnimationFrame(tick); }
    else cancelAnimationFrame(raf);
  };
  play.onclick = () =&gt; toggle(!running);
  range.oninput = e =&gt; { e.stopPropagation(); set(+range.value); };
  chips.onclick = e =&gt; { const b = e.target.closest("button"); if (b) set(+b.dataset.t); };
  root.value = M.liftoff - 20;
  root.rate = 0;
  root.running = false;
  root.setT = set;
  root.setSpeed = v =&gt; { speed.value = v; };
  invalidation.then(() =&gt; cancelAnimationFrame(raf));
  return root;
}







tabAt = (rows, t, n) =&gt; {
  const ts = rows._t ?? (rows._t = rows.map(d =&gt; d[0]));
  const i = Math.max(0, Math.min(rows.length - 2, d3.bisectRight(ts, t) - 1));
  const a = rows[i], b = rows[i + 1], f = Math.max(0, Math.min(1, (t - a[0]) / ((b[0] - a[0]) || 1)));
  return d3.range(1, n + 1).map(j =&gt; a[j] + f * (b[j] - a[j]));
}
rowAt = (rows, t) =&gt; {
  const ts = rows._t ?? (rows._t = rows.map(d =&gt; d[0]));
  return rows[Math.max(0, Math.min(rows.length - 1, d3.bisectRight(ts, t) - 1))];
}
stage = t =&gt; t &lt; M.tei[1] + 2 * 3600 ? "moon" : t &lt; M.ei - 1200 ? "coast" : "entry"
state = {
  const s = {get: T, phase: phases.filter(p =&gt; p[0] &lt;= T).at(-1)[1], stage: stage(T)};
  if (T &lt;= data.lm.at(-1)[0]) {
    const l = tabAt(data.lm, T, 11);
    s.lm = {x: l[0], y: l[1], z: l[2], alt_ft: l[3], hdot: l[4], hvel: l[5], lat: l[6], lon: l[7], mass: l[8]};
    s.src = rowAt(data.lm, T)[10];
  }
  if (T &lt;= data.csm.at(-1)[0]) {
    const c = tabAt(data.csm, T, 7);
    s.csm = {x: c[0], y: c[1], z: c[2], alt: c[3], v: c[4], lat: c[5], lon: c[6]};
    if (s.lm) s.range_km = Math.hypot(c[0] - s.lm.x, c[1] - s.lm.y, c[2] - s.lm.z);
  }
  if (T &gt;= data.earth[0][0] && T &lt; data.entry[0][0]) {
    const e = tabAt(data.earth, T, 6);
    s.earth = {alt: e[3], v: e[4], moon: e[5]};
    s.src = 3;
  }
  if (T &gt;= data.entry[0][0]) {
    const e = tabAt(data.entry, T, 12);
    s.entry = {alt_ft: e[3], v: e[4], vrel: e[5], g: e[6], bank: e[7], lat: e[8], lon: e[9], fpa: e[10]};
    s.src = 3;
  }
  if (T &gt; M.dock_contact) s.src = s.stage === "moon" ? 3 : s.src;
  if (T &gt;= M.splash) s.src = 0;
  return s;
}






























