      &lt;div&gt;&lt;span class="a11-phase"&gt;${s.phase}&lt;/span&gt;
        &lt;span class="a11-pill" style="background:${src.color}"&gt;${src.name}&lt;/span&gt;&lt;/div&gt;
    &lt;/div&gt;
    &lt;div class="a11-hud"&gt;${cells}&lt;/div&gt;&lt;/div&gt;`;
}







