  &lt;/div&gt;`;
  const aSegs = media.audio.flatMap(a =&gt; a.segments.map(s =&gt; ({...s, src: a.src, title: a.title})));
  const vSegs = media.video.flatMap(v =&gt; v.segments.map(s =&gt; ({...s, src: v.src, title: v.title})));
  function update(t) {
    let i = d3.bisectRight(lineT, t) - 1;
    while (i &gt;= 0 && !show[lines[i][4]]) i--;
    if (i !== lastIdx) {
      if (lastIdx &gt;= 0 && rows[lastIdx]) rows[lastIdx].classList.remove("cur");
      if (i &gt;= 0) {
        rows[i].classList.add("cur");
        if (performance.now() - userScroll &gt; 4000) list.scrollTop = rows[i].offsetTop - list.offsetTop - list.clientHeight / 3;
        const [lt, code, who, text, ch] = lines[i];
        now.replaceChildren(htl.html`&lt;div class="who" style="color:${colors[code.split(" ")[0]] ?? "#888"}"&gt;${who}${ch === "onboard" ? " · onboard" : ""}
          &lt;span class="t"&gt;${fmtT(lt)}&lt;/span&gt;&lt;/div&gt;&lt;div class="x"&gt;${text}&lt;/div&gt;`);
      }
      lastIdx = i;
    }
    const realTime = player.running && player.rate === 1;
    const a = aSegs.find(s =&gt; t &gt;= s.get_start && t &lt; s.get_end);
    if (a) {
      if (audio.getAttribute("src") !== a.src) { audio.setAttribute("src", a.src); }
      const want = a.clip_start + (t - a.get_start);
      status.textContent = soundOn ? (realTime ? `Playing: ${a.title}` : "Audio plays at Real time speed") : "NASA audio available here";
      if (soundOn && realTime) {
        if (Math.abs(audio.currentTime - want) &gt; 0.8) audio.currentTime = want;
        if (audio.paused) audio.play().catch(() =&gt; {});
      } else if (!audio.paused) audio.pause();
    } else {
      if (!audio.paused) audio.pause();
      const n = aSegs.filter(s =&gt; s.get_start &gt; t).sort((x, y) =&gt; x.get_start - y.get_start)[0];
      status.textContent = n ? `No audio in the reels here; next at ${fmtT(n.get_start)}` : "No more audio; the Day 9 reel has no captions to place it by";
    }
    const v = vSegs.find(s =&gt; t &gt;= s.get_start && t &lt; s.get_end);
    videoBox.style.display = v ? "" : "none";
    if (v) {
      if (video.getAttribute("src") !== v.src) { video.setAttribute("src", v.src); video.preload = "metadata"; }
      vcap.textContent = `${v.title}: ${v.note}`;
      const rate = v.rate ?? 1, want = v.clip_start + (t - v.get_start) / rate;
      if (realTime) {
        video.playbackRate = 1 / rate;
        if (Math.abs(video.currentTime - want) &gt; 0.4) video.currentTime = want;
        if (video.paused) video.play().catch(() =&gt; {});
      } else { if (!video.paused) video.pause(); if (Math.abs(video.currentTime - want) &gt; 0.15) video.currentTime = want; }
    } else if (!video.paused) video.pause();
  }
  invalidation.then(() =&gt; { audio.pause(); video.pause(); });
  return {el, update};
}







