    &lt;/svg&gt;
    &lt;div class="sl-legend"&gt;&lt;span style="--c:#6c8cff"&gt;True wind ${fmt(tws, 1)} kn&lt;/span&gt;&lt;span style="--c:#bbbbbb"&gt;Headwind from the boat's motion ${fmt(S.v, 1)} kn&lt;/span&gt;&lt;span style="--c:#22d3ee"&gt;Apparent wind ${fmt(S.aws, 1)} kn&lt;/span&gt;&lt;/div&gt;
    &lt;div class="sl-note"&gt;Each arrow shows where the air is going. The boat's motion adds a headwind equal to its speed, so the wind the sails feel is stronger and further forward than the true wind, except when running.&lt;/div&gt;&lt;/div&gt;`;
}







polarPanel = {
  const w = 320, h = 320, cx = 30, cy = 160, R = 135;
  const vmax = 12;
  const r = v =&gt; v / vmax * R;
  const pt = (ang, v) =&gt; [cx + r(v) * Math.sin(ang * Math.PI / 180), cy - r(v) * Math.cos(ang * Math.PI / 180)];
  const curve = M.twa.filter(a =&gt; a &gt;= 30).map(a =&gt; [a, at(tws, a).v]);
  const line = d3.line().x(d =&gt; pt(d[0], d[1])[0]).y(d =&gt; pt(d[0], d[1])[1]);
  const C = data.cert, ci = C.speeds.findIndex(s =&gt; Math.abs(s - tws) &lt; 0.26);
  const certPts = ci &gt;= 0 ? C.angles.map((a, k) =&gt; ({a, m: C.median[k][ci], lo: C.p10[k][ci], hi: C.p90[k][ci]})) : [];
  const vm = data.vmg.reduce((b, v) =&gt; Math.abs(v[0] - tws) &lt; Math.abs(b[0] - tws) ? v : b);
  const upA = vm[1], dnA = vm[3];
  return htl.html`&lt;div class="sl-panel"&gt;&lt;h4&gt;Polar: boat speed at every angle, ${fmt(tws, 1)} knots of wind&lt;/h4&gt;
    &lt;svg viewBox="0 0 ${w} ${h}" width="100%" style="display:block;background:#07111f;border-radius:6px;font-size:10px"&gt;
      ${[2, 4, 6, 8, 10, 12].map(v =&gt; htl.svg`&lt;path d="M${cx},${cy - r(v)} A${r(v)},${r(v)} 0 0 1 ${cx},${cy + r(v)}" fill="none" stroke="#ffffff18"/&gt;&lt;text x=${cx + 3} y=${cy - r(v) + 10} fill="#ffffff70"&gt;${v}&lt;/text&gt;`)}
      ${[0, 30, 60, 90, 120, 150, 180].map(a =&gt; { const p = pt(a, vmax); return htl.svg`&lt;line x1=${cx} y1=${cy} x2=${p[0]} y2=${p[1]} stroke="#ffffff12"/&gt;&lt;text x=${p[0] + 4 * Math.sin(a * Math.PI / 180)} y=${p[1] - 4 * Math.cos(a * Math.PI / 180) + 3} fill="#ffffff70"&gt;${a}°&lt;/text&gt;`; })}
      &lt;path d="M${cx},${cy} L${pt(0, vmax)} A${R},${R} 0 0 1 ${pt(30, vmax)} Z" fill="#e6394622"/&gt;
      &lt;path d=${line(curve)} fill="none" stroke="#f4a261" stroke-width="2.2"/&gt;
      ${certPts.map(c =&gt; { const a = pt(c.a, c.lo), b = pt(c.a, c.hi), m = pt(c.a, c.m); return htl.svg`&lt;line x1=${a[0]} y1=${a[1]} x2=${b[0]} y2=${b[1]} stroke="#2a9d8f" stroke-width="3" opacity=".6"/&gt;&lt;circle cx=${m[0]} cy=${m[1]} r="3.2" fill="#2a9d8f" stroke="#fff" stroke-width=".7"/&gt;`; })}
      &lt;line x1=${cx} y1=${cy} x2=${pt(upA, at(tws, upA).v)[0]} y2=${pt(upA, at(tws, upA).v)[1]} stroke="#9b5de5" stroke-dasharray="3 3"/&gt;
      &lt;line x1=${cx} y1=${cy} x2=${pt(dnA, at(tws, dnA).v)[0]} y2=${pt(dnA, at(tws, dnA).v)[1]} stroke="#9b5de5" stroke-dasharray="3 3"/&gt;
      &lt;circle cx=${pt(twa, S.v)[0]} cy=${pt(twa, S.v)[1]} r="5.5" fill="#e63946" stroke="#fff" stroke-width="1.5"/&gt;
      &lt;text x=${cx + 4} y="14" fill="#ffffff90"&gt;wind from here ↓&lt;/text&gt;
      &lt;text x=${w - 6} y=${h - 8} fill="#ffffff70" text-anchor="end"&gt;boat speed, knots&lt;/text&gt;
    &lt;/svg&gt;
    &lt;div class="sl-legend"&gt;&lt;span style="--c:#f4a261"&gt;Model&lt;/span&gt;&lt;span style="--c:#2a9d8f"&gt;ORC certificates: median, 10–90%${ci &lt; 0 ? " (shown at 6, 8 … 16, 20, 24 kn)" : ""}&lt;/span&gt;&lt;span style="--c:#9b5de5"&gt;Best VMG angles&lt;/span&gt;&lt;span style="--c:#e6394655"&gt;No-go zone&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;`;
