hud = {
  const cell = (k, v, s) =&gt; htl.html`&lt;div&gt;&lt;div class="k"&gt;${k}&lt;/div&gt;&lt;div class="v"&gt;${v}&lt;/div&gt;&lt;div class="s"&gt;${s}&lt;/div&gt;&lt;/div&gt;`;
