    &lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;ORC&lt;/th&gt;&lt;th&gt;model&lt;/th&gt;&lt;th&gt;ORC&lt;/th&gt;&lt;th&gt;model&lt;/th&gt;&lt;th&gt;ORC&lt;/th&gt;&lt;th&gt;model&lt;/th&gt;&lt;th&gt;ORC&lt;/th&gt;&lt;th&gt;model&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;&lt;tbody&gt;
    ${rows.map(r =&gt; htl.html`&lt;tr&gt;&lt;td class="num"&gt;${r.s}&lt;/td&gt;&lt;td class="num"&gt;${fmt(r.ba, 1)}&lt;/td&gt;&lt;td class="num"&gt;${r.mba ?? "–"}&lt;/td&gt;&lt;td class="num"&gt;${fmt(r.bv, 2)}&lt;/td&gt;&lt;td class="num"&gt;${r.mbv != null ? fmt(r.mbv, 2) : "–"}&lt;/td&gt;&lt;td class="num"&gt;${fmt(r.ra, 1)}&lt;/td&gt;&lt;td class="num"&gt;${r.mra ?? "–"}&lt;/td&gt;&lt;td class="num"&gt;${fmt(r.rv, 2)}&lt;/td&gt;&lt;td class="num"&gt;${r.mrv != null ? fmt(r.mrv, 2) : "–"}&lt;/td&gt;&lt;/tr&gt;`)}
    &lt;/tbody&gt;&lt;/table&gt;`;
