viewof twa = {
  const range = Inputs.range([30, 180], {step: 1, value: 45, label: "True wind angle (°)"});
  const play = htl.html`&lt;button type="button" class="primary"&gt;▶ Sweep&lt;/button&gt;`;
  const root = htl.html`&lt;div class="sl-play"&gt;${range}${play}&lt;/div&gt;`;
  root.value = range.value;
  let raf = null, dir = 1, last = null;
  range.addEventListener("input", e =&gt; { e.stopPropagation(); root.value = range.value; root.dispatchEvent(new Event("input", {bubbles: true})); });
  const step = ts =&gt; {
    if (last != null) {
      let v = root.value + dir * (ts - last) / 1000 * 12;
      if (v &gt;= 180) { v = 180; dir = -1; } else if (v &lt;= 30) { v = 30; dir = 1; }
      root.value = v; range.value = Math.round(v);
      root.dispatchEvent(new Event("input", {bubbles: true}));
    }
    last = ts; raf = requestAnimationFrame(step);
  };
  play.onclick = () =&gt; {
    if (raf) { cancelAnimationFrame(raf); raf = null; last = null; play.textContent = "▶ Sweep"; }
    else { play.textContent = "❚❚ Stop"; raf = requestAnimationFrame(step); }
  };
  invalidation.then(() =&gt; raf && cancelAnimationFrame(raf));
  return root;
}







