    &lt;text x=${cx - R * 0.55} y=${cy + 4} text-anchor="middle" font-size="11" fill="currentColor"&gt;port tack&lt;/text&gt;
    &lt;text x=${cx + R * 0.15} y=${cy + R + 18} text-anchor="middle" font-size="11" fill="currentColor"&gt;starboard tack →&lt;/text&gt;
    &lt;circle cx=${cur[0]} cy=${cur[1]} r="6" fill="#e63946" stroke="#fff" stroke-width="1.5"/&gt;
    &lt;g transform="translate(${cx},${cy})"&gt;&lt;path d="M0,-12 C4,-5 4,7 3,12 L-3,12 C-4,7 -4,-5 0,-12Z" fill="#1d3557"/&gt;&lt;/g&gt;
  &lt;/svg&gt;&lt;/div&gt;`;
